/**
 * Cross-language conformance tests.
 *
 * The fixture `conformance/vectors.json` at the repository root is generated by the Rust
 * implementation (`keyless-rust/examples/gen_conformance.rs`), the source of truth for
 * the keyless encoding. This suite verifies that the TypeScript implementation
 * reproduces every vector exactly; the Rust and Python test suites consume the same
 * fixture.
 */
import * as fs from "fs";
import * as path from "path";
import { bytesToHex, hexToBytes } from "@noble/hashes/utils";
import { ss58Decode, ss58Encode } from "../src/ss58";
import {
  AddressType,
  decodeAccountId,
  decodeAddress,
  decodeAppAgentAddress,
  encodeAppAgentAddress,
  encodeNamedAddress,
  encodeTransactionalAddress,
} from "../src/keyless";

interface AppAgentVector {
  id: number;
  hex: string;
  ss58: string;
}

interface TransactionalVector {
  aa: number;
  ta: number;
  hex: string;
  ss58: string;
}

interface NamedVector {
  aa: number;
  name: string;
  hex: string;
  ss58: string;
}

interface ClassifyVector {
  hex: string;
  expected: {
    type: keyof typeof AddressType;
    app_agent_id?: number;
    ta_id?: number;
    name?: string;
  };
}

interface Ss58FormatVector {
  hex: string;
  format: number;
  ss58: string;
}

interface Ss58InvalidVector {
  ss58: string;
  format: number;
  reason: string;
}

interface NamedInvalidEncodeVector {
  name: string;
  reason: string;
}

interface HexInvalidVector {
  hex: string;
  reason: string;
}

interface Vectors {
  app_agent: AppAgentVector[];
  transactional: TransactionalVector[];
  named: NamedVector[];
  classify: ClassifyVector[];
  ss58_formats: Ss58FormatVector[];
  ss58_invalid: Ss58InvalidVector[];
  named_invalid_encode: NamedInvalidEncodeVector[];
  hex_invalid: HexInvalidVector[];
}

const vectorsPath = path.join(
  __dirname,
  "..",
  "..",
  "conformance",
  "vectors.json",
);
const vectors: Vectors = JSON.parse(fs.readFileSync(vectorsPath, "utf8"));

describe("Cross-language conformance vectors (generated by keyless-rust)", () => {
  it("reproduces the AppAgent vectors", () => {
    vectors.app_agent.forEach((v) => {
      expect(encodeAppAgentAddress(v.id)).toEqual(v.ss58);
      const info = decodeAddress(v.ss58);
      expect(info.accountId).toEqual(`0x${v.hex}`);
      expect(info.addressType).toEqual(AddressType.AppAgent);
      expect(info.appAgentId).toEqual(v.id);
      expect(decodeAppAgentAddress(v.ss58)).toEqual(v.id);
    });
  });

  it("reproduces the Transactional vectors", () => {
    vectors.transactional.forEach((v) => {
      expect(encodeTransactionalAddress(v.aa, v.ta)).toEqual(v.ss58);
      const info = decodeAddress(v.ss58);
      expect(info.accountId).toEqual(`0x${v.hex}`);
      expect(info.addressType).toEqual(AddressType.Transactional);
      expect(info.appAgentId).toEqual(v.aa);
      expect(info.taId).toEqual(v.ta);
    });
  });

  it("reproduces the Named vectors", () => {
    vectors.named.forEach((v) => {
      expect(encodeNamedAddress(v.aa, v.name)).toEqual(v.ss58);
      const info = decodeAddress(v.ss58);
      expect(info.accountId).toEqual(`0x${v.hex}`);
      expect(info.addressType).toEqual(AddressType.Named);
      expect(info.appAgentId).toEqual(v.aa);
      expect(info.addressName).toEqual(v.name);
    });
  });

  it("reproduces the classification vectors", () => {
    vectors.classify.forEach((v) => {
      const info = decodeAccountId(`0x${v.hex}`);
      expect(AddressType[info.addressType]).toEqual(v.expected.type);
      expect(info.appAgentId).toEqual(v.expected.app_agent_id ?? null);
      expect(info.taId).toEqual(v.expected.ta_id ?? null);
      expect(info.addressName).toEqual(v.expected.name ?? null);
    });
  });

  it("reproduces the SS58 format vectors", () => {
    vectors.ss58_formats.forEach((v) => {
      // ss58Encode is the encoder behind the encode* functions' ss58Format parameter.
      expect(ss58Encode(hexToBytes(v.hex), v.format)).toEqual(v.ss58);
      const decoded = ss58Decode(v.ss58);
      expect(`0x${bytesToHex(decoded.accountId)}`).toEqual(`0x${v.hex}`);
      expect(decoded.format).toEqual(v.format);
      const info = decodeAddress(v.ss58, v.format);
      expect(info.accountId).toEqual(`0x${v.hex}`);
    });
  });

  it("rejects the invalid SS58 vectors", () => {
    // Address strings that must not decode in any implementation when the accompanying
    // format is expected (non-canonical shapes, reserved formats, corrupted checksums).
    vectors.ss58_invalid.forEach((v) => {
      expect(() => decodeAddress(v.ss58, v.format)).toThrow();
    });
  });

  it("rejects the invalid encode-time names", () => {
    // Names every implementation must reject at encode time.
    vectors.named_invalid_encode.forEach((v) => {
      expect(() => encodeNamedAddress(1, v.name)).toThrow();
    });
  });

  it("rejects the invalid raw account id strings", () => {
    // Strings that violate the "0x" + 64 hex contract of decodeAccountId.
    vectors.hex_invalid.forEach((v) => {
      expect(() => decodeAccountId(v.hex)).toThrow();
    });
  });
});
